<section class="panel subsection" id="markets"><h2>Markets and shows.</h2><p>Apply to join an upcoming market. Pickup stock can be allocated after Markets and Makers approves your participation.</p>@forelse($markets as $market)@php($participation=$market->makers->first()?->pivot)<div class="section-box"><div class="heading-row"><h3>{{ $market->name }}</h3>@if($participation)<span class="badge">{{ $participation->status }}</span>@endif</div><p>{{ $market->starts_at->setTimezone($market->timezone)->format('D, M j · g:i a') }} · {{ $market->address }}@if($participation?->booth)<br>Your booth: {{ $participation->booth }}@endif</p><form method="post" action="/maker/{{ $maker->id }}/markets">@csrf<input type="hidden" name="market_id" value="{{ $market->id }}"><input type="hidden" name="action" value="{{ $participation && in_array($participation->status,['applied','approved','invited']) ? 'withdraw' : 'apply' }}"><button class="button compact secondary">{{ $participation && in_array($participation->status,['applied','approved','invited']) ? 'Withdraw participation' : 'Apply to join' }}</button></form></div>@empty<p>Upcoming market opportunities will appear here.</p>@endforelse</section>
